# The animals that can be adopted.
#
# A character is a module of this package with a CHARACTER dict:
#
#   id           same as the module name
#   name         shown in the game
#   gender       "f" or "m", for the grammar of the messages
#   species      key of prestopet.species.SPECIES: the rules of the simulation
#   personality  multipliers applied to some species rules (see species.make_profile)
#   coat         the art, generated by tools/build_sprites.py: coat_<coat>.py awake and
#                sleep_<coat>.py curled up on a cushion
#   palette      colour of each code used by the coat
#   cushion      colours of the cushion (codes 0 to 4)
#   traits       a short description per language
#
# To add an animal: write its module, add its id to CHARACTERS, and if needed a new coat in
# tools/build_sprites.py. The engine does not change.

from prestopet import species

CHARACTERS = ("louna", "croquette")
RENAMED = {"luna": "louna"}     # ids of older versions, still read in saves


def canonical(cid):
    return RENAMED.get(cid, cid)


def _module(name):
    mod = __import__("prestopet.pets." + name)
    return getattr(mod.pets, name)


def character(cid):
    if cid not in CHARACTERS:
        raise KeyError("unknown character: %r" % (cid,))
    return _module(cid).CHARACTER


def profile(cid):
    c = character(cid)
    return species.make_profile(species.SPECIES[c["species"]], c.get("personality"))


def coat(cid):
    return _module("coat_" + character(cid)["coat"])


def sleep_art(cid):
    return _module("sleep_" + character(cid)["coat"])


def sleep_palette(cid):
    c = character(cid)
    palette = dict(c["palette"])
    palette.update(c["cushion"])
    return palette
